class Solution {
    public int calculate(String s) {
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
        int result = 0, num = 0, sign = 1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == '+') {
                result += sign * num;
                num = 0;
                sign = 1;
            } else if (c == '-') {
                result += sign * num;
                num = 0;
                sign = -1;
            } else if (c == '(') {
                stack.push(result);
                stack.push(sign);
                result = 0;
                sign = 1;
            } else if (c == ')') {
                result += sign * num;
                num = 0;
                result *= stack.pop();
                result += stack.pop();
            }
        }
        return result + sign * num;
    }
}

class Solution {
    private int idx;
    public int calculate(String s) {
        idx = 0;
        return eval(s);
    }
    private int eval(String s) {
        int result = 0;
        int sign = 1;
        while (idx < s.length()) {
            char c = s.charAt(idx);
            if (c == ' ') {
                idx++;
            } else if (c == '(') {
                idx++;
                result += sign * eval(s);
            } else if (c == ')') {
                idx++;
                return result;
            } else if (c == '+') {
                sign = 1;
                idx++;
            } else if (c == '-') {
                sign = -1;
                idx++;
            } else {
                int num = 0;
                while (idx < s.length() && s.charAt(idx) >= '0' && s.charAt(idx) <= '9') {
                    num = num * 10 + (s.charAt(idx) - '0');
                    idx++;
                }
                result += sign * num;
            }
        }
        return result;
    }
}
